import asyncio

async def fetch(attempt):
    if attempt < 2:
        await asyncio.sleep(0.2)
        raise ConnectionError('timeout')
    return f'success {attempt}'

async def main():
    for i in range(3):
        try:
            return await fetch(i)
        except ConnectionError:
            continue
    return 'gave up'

asyncio.run(main())
